// -----------------------------------------------------------------------------
// Just enough XML for what a FRITZ!Box serves: UPnP descriptions, SOAP
// envelopes, the host list and the phone book. These documents are flat and
// generated by the box, so a few regular expressions read them reliably
// without a dependency (the image stays small, the sandbox has 256 MB).
// -----------------------------------------------------------------------------

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

/** Decode the entities and CDATA of a text node; trims it. */
export function decodeXml(text) {
  return String(text ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity) => {
      if (entity[0] === '#') {
        const code =
          entity[1] === 'x' || entity[1] === 'X'
            ? parseInt(entity.slice(2), 16)
            : Number(entity.slice(1));
        return Number.isFinite(code) && code > 0 && code < 0x110000
          ? String.fromCodePoint(code)
          : '';
      }
      return ENTITIES[entity.toLowerCase()] ?? match;
    })
    .trim();
}

/** Escape a value for an XML text node (SOAP arguments). */
export function escapeXml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

const escapeRegExp = (text) => text.replace(/[.*+?^${}()|[\]\\-]/g, '\\$&');

/**
 * Text of the first element named `tag` (any namespace prefix), or null.
 * `<tag/>` and `<tag></tag>` give ''.
 */
export function readTag(xml, tag) {
  const name = escapeRegExp(tag);
  const source = String(xml ?? '');
  const empty = new RegExp(`<(?:[\\w-]+:)?${name}(?:\\s[^>]*)?/>`, 'i');
  const full = new RegExp(
    `<(?:[\\w-]+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)</(?:[\\w-]+:)?${name}>`,
    'i',
  );
  const match = source.match(full);
  const emptyMatch = source.match(empty);
  if (match && (!emptyMatch || match.index <= emptyMatch.index)) {
    return decodeXml(match[1]);
  }
  return emptyMatch ? '' : null;
}

/** The raw inner XML of every element named `tag`, in document order. */
export function blocks(xml, tag) {
  const name = escapeRegExp(tag);
  const pattern = new RegExp(
    `<(?:[\\w-]+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)</(?:[\\w-]+:)?${name}>`,
    'gi',
  );
  return [...String(xml ?? '').matchAll(pattern)].map((match) => match[1]);
}

/** The child elements of a flat block, as `{ name: text }` (first one wins). */
export function children(xml) {
  const result = {};
  const pattern = /<([\w:-]+)(?:\s[^>]*)?(?:\/>|>([\s\S]*?)<\/\1>)/g;
  for (const match of String(xml ?? '').matchAll(pattern)) {
    const name = match[1].replace(/^[\w-]+:/, '');
    if (!(name in result)) {
      result[name] = decodeXml(match[2] ?? '');
    }
  }
  return result;
}
